/*
 * A160592  Indices of primes congruent to 7 modulo 12.
 * https://oeis.org/A160592
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 59, u16 n <= 59, u32 n <= 59, u64 n <= 59, u128 n <= 59,
 *            big any n
 * Helpers:   is_prime, seq_alloc_array, seq_free_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function computes OEIS A160592: indices of primes ≡ 7 (mod 12).  */
/* The sequence is generated by scanning the primes in order and recording
   those whose value is congruent to 7 modulo 12.  The implementation
   keeps an internal cache of the indices so that repeated or out‑of‑order
   calls are answered in O(1).  For n up to about 10 000 all operations
   finish in well under two seconds.  */
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime.h"
#include "../utils/seq_alloc_array.h"
#include "../utils/seq_free_array.h"

/* Grow the cache array when more storage is needed. */
static void
ensure_capacity(idx_t needed, idx_t *cap, seq_t **arr)
{
    if (needed <= *cap)
        return;
    idx_t new_cap = (*cap == 0) ? 32 : (*cap * 2);
    if (new_cap < needed)
        new_cap = needed;
    seq_t *new_arr = seq_alloc_array(new_cap);
    for (idx_t i = 0; i < *cap; ++i)          /* copy existing data   */
        new_arr[i] = (*arr)[i];
    seq_free_array(*arr);                     /* free old buffer      */
    *arr = new_arr;
    *cap = new_cap;
}

/* External linkage as required. */
seq_t a(idx_t n)
{
    if (n == 0)                 /* out of range, behaviour undefined */
        return (seq_t)0;

    static bool initialized = false;
    static seq_t *indices = NULL;    /* cache of desired indices   */
    static idx_t cap = 0, cnt = 0;   /* current capacity & usage   */

    /* Lazily initialise the cache on the first call. */
    if (!initialized) {
        indices = seq_alloc_array(32);
        cap = 32;
        cnt = 0;
        initialized = true;
    }

    /* Generate primes until we have recorded up to a(n). */
    static idx_t current = 2;        /* current candidate number   */
    static idx_t prime_index = 1;    /* 1‑based index of the prime */

    while (cnt < n) {
        bool prime_found;
        if (current == 2)
            prime_found = true;      /* 2 is prime */
        else
            prime_found = is_prime(current);

        if (prime_found) {
            if ((current % 12) == 7) {
                ensure_capacity(cnt + 1, &cap, &indices);
                indices[cnt++] = (seq_t)prime_index;
            }
            ++prime_index;
        }

        /* Advance to the next candidate: after 2 we step by 2 to skip evens. */
        current += (current == 2 ? 1 : 2);
    }

    return indices[n - 1];
}
